/* Alarm widget specific styles */
richlistitem[is="calendar-alarm-widget-richlistitem"] {
  border-block-end: 1px dotted ThreeDShadow;
  padding: 6px 7px;
}

richlistitem[is="calendar-alarm-widget-richlistitem"][selected] {
  padding: 0 5px;
}

richlistitem[is="calendar-alarm-widget-richlistitem"][selected] .alarm-title-label {
  font-weight: bold;
}

richlistitem[is="calendar-alarm-widget-richlistitem"][selected] .alarm-action-buttons {
  display: flex;
  color: var(--field-text-color);
}

richlistitem[is="calendar-alarm-widget-richlistitem"][selected] > hbox {
  margin: 5px;
}

richlistitem[is="calendar-alarm-widget-richlistitem"][selected] .alarm-relative-date-label,
.additional-information-box,
.alarm-action-buttons {
  display: none;
}

richlistitem[is="calendar-alarm-widget-richlistitem"][selected] .additional-information-box,
richlistitem[is="calendar-alarm-widget-richlistitem"][selected] .action-buttons-box {
  display: flex;
}

.alarm-calendar-event {
  overflow: hidden;
}

.alarm-location-description {
  display: flex;
}

.alarm-details-label {
  color: inherit !important;
  text-decoration: underline;
}

.alarm-calendar-image {
  -moz-context-properties: fill;
  fill: currentColor;
  margin-block-start: 2px;
}

richlistitem[is="calendar-alarm-widget-richlistitem"]:not([selected]) .alarm-calendar-image {
  display: none;
}

